// combining a high surrogate with the low surrogate that must follow it.
// It returns the decoded rune and the index just past the escape(s).
func decodeUnicodeEscape(s string, i int) (rune, int, error) {
	r, next, err := parseHexEscape(s, i)
	if err != nil {
		return 0, 0, err
	}
	switch {
	case r >= 0xD800 && r <= 0xDBFF:
		// high surrogate: must be immediately followed by \uDC00–\uDFFF
		if next+1 >= len(s) || s[next] != '\\' || s[next+1] != 'u' {
			return 0, 0, fmt.Errorf("field %q has an unpaired high surrogate in a Unicode escape", "key")
