	for _, c := range s[i+2 : i+6] {
		v <<= 4
		switch {
		case c >= '0' && c <= '9': v += c - '0'
		case c >= 'a' && c <= 'f': v += c - 'a' + 10
		case c >= 'A' && c <= 'F': v += c - 'A' + 10
		default:
			return 0, 0, fmt.Errorf("field %q has a non-hex digit in a Unicode escape", "key")
		}
	}
	return v, i + 6, nil
